/**
 * Kafka Consumer Manager — Manages dynamic Kafka consumers for runtime agents.
 * Creates and destroys Kafka consumers based on agent configurations.
 * Generated by Mindbricks Genesis Engine for the AgentHub service.
 */

// Active consumers: Map<agentName, Map<controllerName, consumer>>
const activeConsumers = new Map();

let kafkaClient = null;

/**
 * Initialize the Kafka client (reuses the service's existing Kafka connection).
 */
function initKafkaClient() {
  if (kafkaClient) return kafkaClient;

  try {
    const { KafkaListener } = require("common");
    kafkaClient = KafkaListener;
    return kafkaClient;
  } catch (err) {
    console.warn("[KafkaConsumerManager] Kafka not available:", err.message);
    return null;
  }
}

/**
 * Start Kafka consumers for a single agent's kafka controllers.
 */
async function startAgentConsumers(agentName, kafkaControllers, agentExecutor) {
  if (!kafkaControllers || !Array.isArray(kafkaControllers)) return;

  const KafkaListener = initKafkaClient();
  if (!KafkaListener) return;

  const agentConsumers = new Map();
  const serviceCodename = process.env.SERVICE_CODENAME || "agenthub";

  for (const controller of kafkaControllers) {
    if (!controller.enabled || !controller.name || !controller.topic) continue;

    const groupId =
      controller.groupId ||
      `${serviceCodename}-agent-${agentName}-${controller.name}`;

    try {
      const listener = new KafkaListener({
        topic: controller.topic,
        groupId,
        handler: async (message) => {
          try {
            const parsed =
              typeof message.value === "string"
                ? JSON.parse(message.value)
                : message.value;

            // Apply data mapping if provided
            let input = parsed;
            if (controller.dataMapping) {
              try {
                const mapFn = new Function(
                  "message",
                  "topic",
                  "headers",
                  `return (${controller.dataMapping})`,
                );
                input = mapFn(parsed, controller.topic, message.headers || {});
              } catch (mapErr) {
                console.warn(
                  `[KafkaConsumerManager] Data mapping failed for ${agentName}/${controller.name}:`,
                  mapErr.message,
                );
                input = { prompt: JSON.stringify(parsed) };
              }
            }

            // Execute the agent
            if (agentExecutor) {
              await agentExecutor(agentName, input, {
                source: "kafka",
                controller: controller.name,
              });
            }
          } catch (err) {
            console.error(
              `[KafkaConsumerManager] Handler error for ${agentName}/${controller.name}:`,
              err.message,
            );
          }

          return { eventProcess: true };
        },
      });

      await listener.start();
      agentConsumers.set(controller.name, listener);
      console.log(
        `[KafkaConsumerManager] Started consumer: ${agentName}/${controller.name} on topic ${controller.topic}`,
      );
    } catch (err) {
      console.error(
        `[KafkaConsumerManager] Failed to start consumer ${agentName}/${controller.name}:`,
        err.message,
      );
    }
  }

  if (agentConsumers.size > 0) {
    activeConsumers.set(agentName, agentConsumers);
  }
}

/**
 * Stop all Kafka consumers for a specific agent.
 */
async function stopAgentConsumers(agentName) {
  const agentConsumers = activeConsumers.get(agentName);
  if (!agentConsumers) return;

  for (const [controllerName, listener] of agentConsumers) {
    try {
      await listener.stop?.();
      console.log(
        `[KafkaConsumerManager] Stopped consumer: ${agentName}/${controllerName}`,
      );
    } catch (err) {
      console.warn(
        `[KafkaConsumerManager] Error stopping ${agentName}/${controllerName}:`,
        err.message,
      );
    }
  }

  activeConsumers.delete(agentName);
}

/**
 * Restart consumers for an agent (stop old, start new from updated config).
 */
async function restartAgentConsumers(
  agentName,
  kafkaControllers,
  agentExecutor,
) {
  await stopAgentConsumers(agentName);
  await startAgentConsumers(agentName, kafkaControllers, agentExecutor);
}

async function startDynamicKafkaConsumers() {
  // Dynamic agents not enabled
}

/**
 * Stop all active consumers (called at service shutdown).
 */
async function stopAllConsumers() {
  for (const [agentName] of activeConsumers) {
    await stopAgentConsumers(agentName);
  }
  console.log("[KafkaConsumerManager] All consumers stopped");
}

module.exports = {
  startAgentConsumers,
  stopAgentConsumers,
  restartAgentConsumers,
  startDynamicKafkaConsumers,
  stopAllConsumers,
  activeConsumers,
};
